import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  return (
    <div style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>👋 Welcome, {user?.name}!</h1>
      <p>Your study planner dashboard</p>
      <div style={{ display: 'flex', gap: '1rem', marginTop: '1rem' }}>
        <button onClick={() => navigate('/subjects')}
          style={btnStyle('#4f46e5')}>📚 Manage Subjects</button>
        <button onClick={() => navigate('/timetable')}
          style={btnStyle('#10b981')}>📅 View Timetable</button>
        <button onClick={logout}
          style={btnStyle('#ef4444')}>🚪 Logout</button>
      </div>
    </div>
  );
}

const btnStyle = (bg) => ({
  padding: '10px 20px', background: bg, color: 'white',
  border: 'none', borderRadius: '8px', cursor: 'pointer', fontSize: '15px'
});
